#include <chrono>
#include <cmath>
#include <iomanip>
#include <iostream>
#include <string>

#include "Halide.h"

// include common definitions (DATA_TYPE, W, H, etc)
#include "defines.hpp"

// include benchmark-specific definitions (if any)
#include "deriche.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/*
 * Array initialization: replicate the Polybench init_array,
 * but using Halide::Buffer for the arrays.
 */
static void init_array(int w,
                       int h,
                       num_t *alpha,
                       Halide::Buffer<num_t, 2> imgIn,
                       Halide::Buffer<num_t, 2> imgOut) {
    // Silence unused parameter warnings (sizes are implied by the Buffers).
    (void)w;
    (void)h;

    // Parameter of the filter.
    *alpha = (num_t)0.25;

    // imgIn[i][j] = ((313*i + 991*j) % 65536) / 65535.0f;
    //
    // In C: imgIn has type [W][H] and is accessed as imgIn[i][j].
    // The second index j is the fastest varying. In Halide::Buffer,
    // the first dimension is the fastest varying, so we map:
    //   imgIn(i_c, j_c)  <->  imgIn(j_c, i_c)
    // and allocate Buffer(h, w).
    Var i("i"), j("j");
    Func init_in("init_in");

    Expr val = (313 * i + 991 * j) % 65536;
    init_in(j, i) = cast<num_t>(val) / cast<num_t>(65535.0f);

    // A simple but cache‑friendly schedule: tile over j (fast dim) and i,
    // vectorize across j, and parallelize outer tiles in i.
    Var jo("jo"), ji("ji"), io("io"), ii("ii");
    const int vec_width = 8;      // reasonable default for modern x64 (8 floats / AVX2)
    const int tile_j    = 128;
    const int tile_i    = 32;

    init_in
        .compute_root()
        .tile(j, i, jo, io, ji, ii, tile_j, tile_i)
        .vectorize(ji, vec_width)
        .parallel(io);

    // Fill imgIn.
    init_in.realize(imgIn);

    // imgOut is not initialized in the original C code, but we'll
    // set it to zero for completeness (and to avoid denormals, etc.).
    Func init_out("init_out");
    init_out(j, i) = cast<num_t>(0);

    init_out
        .compute_root()
        .tile(j, i, jo, io, ji, ii, tile_j, tile_i)
        .vectorize(ji, vec_width)
        .parallel(io);

    init_out.realize(imgOut);
}

int main(int argc, char *argv[]) {
    // Problem size (Polybench constants).
    int w = W;
    int h = H;

    // Allocate arrays as Halide buffers.
    //
    // C layout: imgIn[w][h]   -> indices imgIn[i][j]
    // Halide   : Buffer(h, w) -> indices imgIn(j, i)
    Halide::Buffer<num_t, 2> imgIn(h, w);
    Halide::Buffer<num_t, 2> imgOut(h, w);
    Halide::Buffer<num_t, 2> y1(h, w);
    Halide::Buffer<num_t, 2> y2(h, w);

    // Transposed work buffers used to improve locality of the vertical passes.
    // Shape (w, h): first dimension is the original row index i.
    Halide::Buffer<num_t, 2> tmp(w, h);
    Halide::Buffer<num_t, 2> y1_t(w, h);
    Halide::Buffer<num_t, 2> y2_t(w, h);
    Halide::Buffer<num_t, 2> imgOut_t(w, h);

    // Scalar parameter.
    num_t alpha;

    // Initialize input.
    init_array(w, h, &alpha, imgIn, imgOut);

    // --------------------------------------------------------------------
    // Halide pipelines for the pointwise pieces:
    //   * two combinations imgOut = c * (y1 + y2)
    //   * a generic transpose used to turn strided vertical passes into
    //     cache‑friendly horizontal ones.
    // --------------------------------------------------------------------
    Var x("x"), y("y");

    // y1 and y2 will be passed into Halide as ImageParams.
    ImageParam y1_param(type_of<num_t>(), 2, "y1_param");
    ImageParam y2_param(type_of<num_t>(), 2, "y2_param");

    // Combination Funcs.
    Func combine1("combine1");
    Func combine2("combine2");

    num_t c1 = (num_t)1;
    num_t c2 = (num_t)1;

    combine1(x, y) = c1 * (y1_param(x, y) + y2_param(x, y));
    combine2(x, y) = c2 * (y1_param(x, y) + y2_param(x, y));

    // Transpose Func: given an input ImageParam, produce its transpose.
    // We will reuse the same Func for both directions by changing the
    // bound ImageParam and the realization Buffer shape.
    ImageParam img_param(type_of<num_t>(), 2, "img_param");
    Func transpose_f("transpose_f");
    transpose_f(x, y) = img_param(y, x);

    // -----------------------
    // Scheduling for Halide.
    // -----------------------
    Var xo("xo"), yo("yo"), xi("xi"), yi("yi");
    const int vec_width = 8;   // tuned for mainstream AVX2 x64
    const int tile_x    = 128;
    const int tile_y    = 32;

    // Row‑major traversal: x (dim 0) is the fast dimension.
    // Tile, vectorize across x, parallelize across tiles of y.
    combine1
        .compute_root()
        .tile(x, y, xo, yo, xi, yi, tile_x, tile_y)
        .vectorize(xi, vec_width)
        .parallel(yo);

    combine2
        .compute_root()
        .tile(x, y, xo, yo, xi, yi, tile_x, tile_y)
        .vectorize(xi, vec_width)
        .parallel(yo);

    // Transpose is also heavily memory‑bound, so we give it a similar
    // schedule.
    transpose_f
        .compute_root()
        .tile(x, y, xo, yo, xi, yi, tile_x, tile_y)
        .vectorize(xi, vec_width)
        .parallel(yo);

    // JIT-compile the small Halide pipelines in advance so we don't
    // measure compilation time.
    Target target = get_host_target();
    combine1.compile_jit(target);
    combine2.compile_jit(target);
    transpose_f.compile_jit(target);

    // --------------------------------------------------------------------
    // Compute Deriche filter coefficients on the host (scalar math).
    // This mirrors the Polybench kernel_deriche coefficient setup.
    // --------------------------------------------------------------------
    num_t ea   = std::exp(-alpha);                 // exp(-alpha)
    num_t e2a  = std::exp(num_t(2.0) * alpha);     // exp(2*alpha)
    num_t e_2a = std::exp(num_t(-2.0) * alpha);    // exp(-2*alpha)

    num_t k = (num_t(1.0) - ea) * (num_t(1.0) - ea) /
              (num_t(1.0) + num_t(2.0) * alpha * ea - e2a);

    num_t a1 = k;
    num_t a5 = k;

    num_t a2 = k * ea * (alpha - num_t(1.0));
    num_t a6 = a2;

    num_t a3 = k * ea * (alpha + num_t(1.0));
    num_t a7 = a3;

    num_t a4 = -k * e_2a;
    num_t a8 = a4;

    num_t b1 = std::pow(num_t(2.0), -alpha);
    num_t b2 = -e_2a;

    // --------------------------------------------------------------------
    // Main computational kernel: Deriche filter.
    //
    // Horizontal IIR recurrences are evaluated directly in C++ over
    // contiguous memory (good locality). The vertical IIR recurrences
    // are transformed into horizontal recurrences via a Halide
    // transpose, so they also run over contiguous memory. The purely
    // pointwise combinations and transposes are done with Halide.
    //
    // Buffer indexing:
    //   original C:   imgIn[i][j]
    //   Halide here:  imgIn(j, i)
    // where i in [0, w) and j in [0, h).
    // --------------------------------------------------------------------

    auto start = std::chrono::high_resolution_clock::now();

    // 1) Horizontal forward recursion (left -> right).
    //    For each row i, we traverse j in the fast (dim 0) direction.
    for (int i = 0; i < w; ++i) {
        num_t ym1 = num_t(0);
        num_t ym2 = num_t(0);
        num_t xm1 = num_t(0);

        for (int j = 0; j < h; ++j) {
            num_t x_ij = imgIn(j, i);
            num_t y_ij = a1 * x_ij + a2 * xm1 + b1 * ym1 + b2 * ym2;
            y1(j, i) = y_ij;

            xm1 = x_ij;
            ym2 = ym1;
            ym1 = y_ij;
        }
    }

    // 2) Horizontal backward recursion (right -> left).
    for (int i = 0; i < w; ++i) {
        num_t yp1 = num_t(0);
        num_t yp2 = num_t(0);
        num_t xp1 = num_t(0);
        num_t xp2 = num_t(0);

        for (int j = h - 1; j >= 0; --j) {
            num_t y_ij = a3 * xp1 + a4 * xp2 + b1 * yp1 + b2 * yp2;
            y2(j, i) = y_ij;

            xp2 = xp1;
            xp1 = imgIn(j, i);
            yp2 = yp1;
            yp1 = y_ij;
        }
    }

    // 3) First pointwise combination:
    //    imgOut[i][j] = c1 * (y1[i][j] + y2[i][j]);
    //    Implemented as a tiled/vectorized Halide Func.
    y1_param.set(y1);
    y2_param.set(y2);
    combine1.realize(imgOut);

    // 4) Transpose imgOut into tmp to make the subsequent "vertical"
    //    recurrences run over contiguous memory.
    //
    //    tmp(i, j) = imgOut(j, i)  <=>  tmp holds imgOut in (i,j) order.
    img_param.set(imgOut);
    transpose_f.realize(tmp);

    // 5) Vertical forward recursion (top -> bottom),
    //    now expressed as a horizontal recursion along i over tmp.
    //
    //    For each column j in the original orientation we now process a
    //    row j in tmp, which keeps the DP direction contiguous.
    for (int j = 0; j < h; ++j) {
        num_t tm1 = num_t(0);
        num_t ym1 = num_t(0);
        num_t ym2 = num_t(0);

        for (int i = 0; i < w; ++i) {
            num_t x_ij = tmp(i, j);  // == imgOut(j, i) in original layout
            num_t y_ij = a5 * x_ij + a6 * tm1 + b1 * ym1 + b2 * ym2;
            y1_t(i, j) = y_ij;

            tm1 = x_ij;
            ym2 = ym1;
            ym1 = y_ij;
        }
    }

    // 6) Vertical backward recursion (bottom -> top),
    //    again as a horizontal recursion along i over tmp.
    for (int j = 0; j < h; ++j) {
        num_t tp1 = num_t(0);
        num_t tp2 = num_t(0);
        num_t yp1 = num_t(0);
        num_t yp2 = num_t(0);

        for (int i = w - 1; i >= 0; --i) {
            num_t y_ij = a7 * tp1 + a8 * tp2 + b1 * yp1 + b2 * yp2;
            y2_t(i, j) = y_ij;

            tp2 = tp1;
            tp1 = tmp(i, j);  // == imgOut(j, i)
            yp2 = yp1;
            yp1 = y_ij;
        }
    }

    // 7) Final pointwise combination in transposed space:
    //    imgOut_t[i][j] = c2 * (y1_t[i][j] + y2_t[i][j]);
    y1_param.set(y1_t);
    y2_param.set(y2_t);
    combine2.realize(imgOut_t);

    // 8) Transpose back to the original layout so that imgOut(j,i)
    //    matches the original C kernel's imgOut[i][j].
    img_param.set(imgOut_t);
    transpose_f.realize(imgOut);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // --------------------------------------------------------------------
    // Output and timing, similar style to example/gemm.cpp.
    // --------------------------------------------------------------------
    using namespace std::string_literals;

    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(6);
        for (int i = 0; i < w; ++i) {
            for (int j = 0; j < h; ++j) {
                // Original C prints imgOut[i][j]; here we map to imgOut(j, i).
                std::cerr << imgOut(j, i) << '\n';
            }
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
