    //   imgIn[i][j]  with i in [0, w), j in [0, h), and j the fast dimension.
    //
    // Halide::Buffer layout here:
    //   Buffer(h, w) and we access as imgIn(j, i),
    //   so dimension 0 (x) corresponds to j (fast),
    //   and dimension 1 (y) corresponds to i (slow).
    //
    // We generate the same initialization formula, but in a layout
    // that is cache‑friendly for the inner j loop.
    Var i("i"), j("j");

    Func init_in("init_in");
    // Polybench formula: imgIn[i][j] = ((313*i + 991*j) % 65536) / 65535.0f;
    Expr val = (313 * i + 991 * j) % 65536;
    // Make all scalar literals explicit Exprs to keep Halide's type system happy.
    Expr denom = cast<num_t>(Expr(65535.0f));
    init_in(j, i) = cast<num_t>(val) / denom;

    Func init_out("init_out");
    init_out(j, i) = cast<num_t>(Expr(0.0f));

    // -----------------------------
    // Schedule for initialization.
    // -----------------------------
    //
    // We want row‑major access in j (the fast dimension),
    // and to exploit SIMD and threads. The tile shape can be tuned;
    // we pick a moderate tile that plays well with L1/L2 caches.
    Target target = get_host_target();
    const int vec = target.natural_vector_size(type_of<num_t>());

    Var xo("xo"), yo("yo"), xi("xi"), yi("yi");

    // imgIn init: tile and vectorize along j (dimension 0),
    // parallelize across tiles in i (dimension 1).
    init_in
        .compute_root()
        .tile(j, i, xo, yo, xi, yi, vec * 4, 32)
        .vectorize(xi, vec)
        .parallel(yo);

    // imgOut init is purely for cleanliness; it is cheap but we still
    // make it contiguous and parallel.
    init_out
        .compute_root()
        .tile(j, i, xo, yo, xi, yi, vec * 4, 32)
        .vectorize(xi, vec)
        .parallel(yo);

    // JIT once; cost is outside the timed region in main().
    init_in.compile_jit(target);
    init_out.compile_jit(target);

    // Fill imgIn and imgOut.
    init_in.realize(imgIn);
    init_out.realize(imgOut);
}

