    // and to exploit SIMD and parallelism over tiles.
    Target target = get_host_target();
    const int vec = target.natural_vector_size(type_of<num_t>());

    Var xo("xo"), yo("yo"), xi("xi"), yi("yi");

    combine
        .compute_root()
        // Tile the 2D domain for good cache locality. We tile along the
        // fast dimension using a multiple of the natural SIMD width, and
        // process several rows per tile to amortize overhead.
        .tile(x, y, xo, yo, xi, yi, vec * 4, 32)
        .vectorize(xi, vec)  // SIMD along the contiguous x dimension.
        .parallel(yo);       // Parallelize across tiles in y.

