    num_t c1 = (num_t)1;
    num_t c2 = (num_t)1;

    // --------------------------------------------------------------------
    // Main computational kernel: Deriche filter.
    //
    // The Deriche filter is an IIR filter with loop‑carried dependencies
    // (recurrences) along rows and columns. General recurrences such as
    // y(i,j) depending on y(i,j‑1) and y(i,j‑2) cannot be expressed as
    // legal Halide update definitions (they would violate Halide's rule
    // that recursive references use the same pure coordinates), so we
    // implement those recurrences as explicit C++ loops over Buffers.
    //
    // All purely pointwise work (the two combinations) is expressed as
    // Halide Funcs with an optimized schedule.
    //
    // Buffer indexing:
    //   original C:   imgIn[i][j]
    //   Halide here:  imgIn(j, i)
    // where i in [0, w) and j in [0, h).
    // Dimension 0 (x) = j (fast), dimension 1 (y) = i (slow).
    // --------------------------------------------------------------------

    auto start = std::chrono::high_resolution_clock::now();

