    // For each original row i, we sweep j from left to right. The
    // inner loop j touches imgIn(j, i) with unit‑stride access since
    // dimension 0 is contiguous. This gives good spatial locality.
    for (int i = 0; i < w; ++i) {
        num_t ym1 = num_t(0);
        num_t ym2 = num_t(0);
        num_t xm1 = num_t(0);

