    // scalar scale param, then realize into imgOut. The Halide schedule
    // computes imgOut in tiles that are vectorized and parallelized
    // across rows for good cache and core utilization.
    y1_param.set(y1);
    y2_param.set(y2);
    scale.set(c1);
    combine.realize(imgOut);

