    for (int j = 0; j < h; ++j) {
        num_t tp1 = num_t(0);
        num_t tp2 = num_t(0);
        num_t yp1 = num_t(0);
        num_t yp2 = num_t(0);

        for (int i = w - 1; i >= 0; --i) {
            num_t y_ij = a7 * tp1 + a8 * tp2 + b1 * yp1 + b2 * yp2;
            y2(j, i) = y_ij;

            tp2 = tp1;
            tp1 = imgOut(j, i);
            yp2 = yp1;
            yp1 = y_ij;
        }
    }

